import assert from 'node:assert/strict';import {mkdirSync,writeFileSync,readFileSync} from 'node:fs';import {chromium,webkit} from 'playwright';import {chapterCollections} from '../lib/practice-chapters.ts';import {learningGoalFor} from '../lib/learning-goals.ts';
const inventory=JSON.parse(readFileSync('outputs/goal-audit-20261101/inventory.json'));const base=process.env.KLINK_TEST_URL||'http://127.0.0.1:18996',out=process.env.KLINK_GOALS_OUTPUT||'outputs/learning-goals-20261101/sheets';mkdirSync(out,{recursive:true});const checks=[],errors=[];
for(const[engine,type]of Object.entries({chromium,webkit})){const browser=await type.launch();try{for(const[width,height]of[[390,844],[320,568]])for(const theme of['light','dark'])for(const activity of['worksheet','worksheet-heard','meet','same-word','listen','hear-word','read','build-model','build','missing','copy','dictation']){
 const c=inventory.cases.find(c=>c.activity===activity),row=chapterCollections(activity).find(r=>r.id===c.collection);if(row.contentUrl)row.exercises=JSON.parse(readFileSync('public'+row.contentUrl)).exercises;const p=await browser.newPage({viewport:{width,height},hasTouch:true,colorScheme:theme});p.setDefaultTimeout(15000);p.on('pageerror',e=>errors.push(e.message));await p.goto(base+c.route);if(!activity.startsWith('worksheet'))await p.getByRole('button',{name:'Op één blad',exact:true}).tap();
 const item=p.locator(activity.startsWith('worksheet')?'[data-worksheet-exercise]':'[data-sheet-exercise]').first();await item.waitFor();const attr=activity.startsWith('worksheet')?'data-worksheet-exercise':'data-sheet-exercise',id=await item.getAttribute(attr),e=row.exercises.find(e=>e.exerciseId===id);assert(e,activity+":"+id);const goal=learningGoalFor(e),trigger=item.getByRole('button',{name:'Over deze oefening',exact:true});assert(await trigger.evaluate(e=>!!e.closest('header')),'per-item info in fixed header');await trigger.press('Enter');const dialog=p.getByRole('dialog');await dialog.waitFor();await p.waitForTimeout(150);assert.equal(await dialog.locator('[data-learning-goal]').getAttribute('data-learning-goal'),goal.id);assert(await dialog.evaluate(e=>{const r=e.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight&&r.left>=0&&r.right<=innerWidth;}));await p.keyboard.press('Tab');await p.keyboard.press('ArrowRight');assert(await dialog.evaluate(e=>e.contains(document.activeElement)));await p.keyboard.press('Escape');await dialog.waitFor({state:'hidden'});assert.equal(await item.getAttribute(attr),id);assert(await trigger.evaluate(e=>e===document.activeElement));const fits=await item.locator('.cp-exercise-tools').evaluate(e=>{const r=e.getBoundingClientRect();return r.left>=0&&r.right<=innerWidth+1;});assert(fits);checks.push({engine,width,height,theme,activity,goal:goal.id,dialogFits:true,toolbarFits:true,keyboardContained:true,focusRestored:true,exercisePreserved:true});await p.close();
 }}finally{await browser.close();writeFileSync(out+'/checks.json',JSON.stringify({base,checks,errors},null,2)+'\n');}}
assert.equal(checks.length,96);assert.deepEqual(errors,[]);console.log('PASS 96 per-item worksheet/sheet goal, touch, keyboard and layout checks');
